"use client";

/* eslint-disable jsx-a11y/no-static-element-interactions, jsx-a11y/no-noninteractive-element-interactions, jsx-a11y/click-events-have-key-events */

import { FormEvent, type ReactNode, useEffect, useState } from "react";

type Plan = { id: string; title: string; scope: string; horizon: string; cycle: string; progress: number; maturity: number; status: "Vigente" | "Em revisão" | "Em elaboração"; owner: string; version: string; center: [number, number] };
type Program = { id: string; planId: string; title: string; axis: string; owner: string; actions: number; progress: number; budget: number; benefit: string; status: "Nominal" | "Atenção" | "Crítico" };
type PlanAction = { id: string; programId: string; title: string; territory: string; owner: string; start: string; due: string; progress: number; budget: number; priority: "P1" | "P2" | "P3"; status: "Planejada" | "Em execução" | "Atenção" | "Concluída"; dependencies: string[]; center: [number, number] };
type Project = { id: string; actionId: string; title: string; stage: number; gate: string; sponsor: string; capex: number; risk: number; readiness: number; status: "Estruturação" | "Gate humano" | "Contratação" | "Execução" | "Operação" };
type Investment = { id: string; projectId: string; title: string; source: string; planned: number; committed: number; executed: number; year: string; territory: string; status: "Previsto" | "Empenhado" | "Executando" | "Concluído" };
type Goal = { id: string; title: string; indicator: string; baseline: number; target: number; current: number; unit: string; due: string; source: string; quality: number; trend: "Subindo" | "Estável" | "Descendo"; status: "No prazo" | "Atenção" | "Fora da meta" };
type PlanningResult = { id: string; actionId: string; title: string; observed: string; benefit: string; evidence: string; contribution: number; verifiedAt: string; status: "Proposto" | "Verificado" | "Em avaliação" };
type PlanningHubProps = { contextItem: string; territory: string; clockLabel: string; onNavigate: (item: string) => void; onOpenModule: (moduleId: string) => void; onToast: (message: string) => void };

